import{z as p,x as E,o as e,c as h,q as o,j as l,D as t,d as i,s as m,S as n,b as r}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"最弱前置条件","description":"","frontmatter":{"title":"最弱前置条件","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/weakest-precondition.md","filePath":"cs/weakest-precondition.md","lastUpdated":1791063341000}'),d={name:"cs/weakest-precondition.md"};function A(B,a,C,w,_,S){const s=E("Mermaid");return e(),h("div",null,[a[2]||(a[2]=o('<h1 id="最弱前置条件" tabindex="-1">最弱前置条件 <a class="header-anchor" href="#最弱前置条件" aria-label="Permalink to &quot;最弱前置条件&quot;">​</a></h1><div class="epigraph"><p>$\\mathrm{wp}(S,Q)$ 是使 $S$ 执行后 $Q$ 成立的最弱前置。Dijkstra 用它定义语义：从后往前算，循环变成不动点。</p><footer>—— 据 Dijkstra, A Discipline of Programming, 1976；Winskel 整理</footer></div><p>上一课<a href="/cs/hoare-logic">Hoare 逻辑</a> 的三元组要人提供 \\(P\\) 与不变式。缺口是<strong>最弱前置</strong> \\(\\mathrm{wp}(S,Q)\\)：\\(\\{P\\}S\\{Q\\}\\) 部分正确当且仅当 \\(P\\Rightarrow\\mathrm{wp}(S,Q)\\)（在终止版本下还有「必停」）。本课给赋值、顺序、if 的等式；while 用 \\(\\mu\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(\\mathrm{wp}(x:=e,Q)=Q[e/x]\\)。\\(\\mathrm{wp}(S_1;S_2,Q)=\\mathrm{wp}(S_1,\\mathrm{wp}(S_2,Q))\\)。\\(\\mathrm{wp}(\\mathrm{if}\\ b\\ S_1\\ S_2,Q)=(b\\land\\mathrm{wp}(S_1,Q))\\lor(\\neg b\\land\\mathrm{wp}(S_2,Q))\\)。循环：\\(\\mathrm{wp}(\\mathrm{while}\\ b\\ S,Q)\\) 是最弱的 \\(I\\)，满足 \\(I\\iff(\\neg b\\land Q)\\lor(b\\land\\mathrm{wp}(S,I))\\)——即某个单调变换的最弱不动点 / 最大前不动点，说法随部分/完全正确而变。本课要「循环 = 不动点方程」，计算下一课 Knaster–Tarski。</p><p>\\(\\mathrm{sp}\\)（最强后置）从前往后，对符号执行更亲。点名。</p><p><span class="marginnote">数字实例：\\(Q\\) 是 \\(x\\gt0\\)，语句 \\(x:=x+1\\)，代入得 \\(\\mathrm{wp}=x+1\\gt0\\)，即 \\(x\\gt-1\\)——这正是能让后条件成立的最大起始集合，比人手写的 \\(x\\ge0\\) 更弱。</span></p><h3 id="最弱不是「最容易证」" tabindex="-1">最弱不是「最容易证」 <a class="header-anchor" href="#最弱不是「最容易证」" aria-label="Permalink to &quot;最弱不是「最容易证」&quot;">​</a></h3><p>最弱 \\(P\\) 允许最多起始状态，公式可能更复杂。人写的不变式往往强于 \\(\\mathrm{wp}\\)，但更好证。</p><p><span class="marginnote">Dijkstra 1976；谓词变换器。ESC/Java、Boogie 把 VC 生成建成工具，本课不写前端。完全正确的 wp 要求体降低变式。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对无循环程序从后往前算一遍 \\(\\mathrm{wp}\\)。指出循环必须近似不动点或给不变式当归纳假设。对照赋值公理：它正是 \\(\\mathrm{wp}\\) 的特例。</p><p><span class="marginnote">常见误区：「最弱」不是「最好证」——\\(\\mathrm{wp}\\) 给出的是能跑通的最大状态集，公式可能又长又怪；工程师给个更强的直觉不变式（如 \\(x\\ge0\\)），证明往往反而更短。</span></p>',13)),(e(),l(n,null,{default:t(()=>[m(s,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%90%8E%E6%9D%A1%E4%BB%B6%20Q%22%5D%20--%3E%20WP%5B%22wp(S%2CQ)%22%5D%0A%20%20WP%20--%3E%20PRE%5B%22%E5%90%88%E6%B3%95%E5%89%8D%E7%BD%AE%20P%20%E2%87%92%20wp%22%5D%0A%20%20WP%20--%3E%20FIX%5B%22while%EF%BC%9A%E4%B8%8D%E5%8A%A8%E7%82%B9%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[i("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"验证条件生成：用户给不变式，工具检查体保持、进入、退出，即若干 \\(\\mathrm{wp}\\) 蕴含。SMT 后课吃这些公式。没有不变式则要对循环求不动点——有限域上即模型检验的前/后像，再后课。",-1)),a[5]||(a[5]=r("p",null,[r("span",{class:"marginnote"},"术语翻译：验证条件（VC）就是工具替你做的几次代入检查——它不真正「跑」程序，而是把「执行后 \\(Q\\) 成立」翻译成几条一阶公式，丢给 SMT 求解器判真假。")],-1)),(e(),l(n,null,{default:t(()=>[m(s,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E5%89%8D%E7%BD%AE%20P%20%E4%B8%8E%E4%B8%8D%E5%8F%98%E5%BC%8F%20I%22%5D%20--%3E%20C1%7B%22%E8%BF%9B%E5%85%A5%EF%BC%9AP%20%E2%87%92%20I%EF%BC%9F%22%7D%0A%20%20C1%20--%3E%7C%22%E9%80%9A%E8%BF%87%22%7C%20C2%7B%22%E4%BF%9D%E6%8C%81%EF%BC%9AI%E2%88%A7b%20%E2%87%92%20wp(S%2CI)%EF%BC%9F%22%7D%0A%20%20C2%20--%3E%7C%22%E9%80%9A%E8%BF%87%22%7C%20C3%7B%22%E9%80%80%E5%87%BA%EF%BC%9AI%E2%88%A7%C2%ACb%20%E2%87%92%20Q%EF%BC%9F%22%7D%0A%20%20C3%20--%3E%7C%22%E4%B8%89%E6%9D%A1%E5%85%A8%E8%BF%87%22%7C%20OK%5B%22%E5%BE%AA%E7%8E%AF%E9%83%A8%E5%88%86%E6%AD%A3%E7%A1%AE%22%5D%0A%20%20C1%20--%3E%7C%22%E5%A4%B1%E8%B4%A5%22%7C%20FIX%5B%22%E5%8A%A0%E5%BC%BA%E4%B8%8D%E5%8F%98%E5%BC%8F%E6%88%96%E6%94%B9%20P%22%5D%0A%20%20C2%20--%3E%7C%22%E5%A4%B1%E8%B4%A5%22%7C%20FIX%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p>可靠：谓词变换器与操作语义一致。</p><p>Dijkstra 的卫式命令：\\(\\mathrm{wp}(S_0\\square S_1,Q)=\\mathrm{wp}(S_0,Q)\\land\\mathrm{wp}(S_1,Q)\\) 当两条都可执行。魔命令 \\(\\mathbf{abort}\\) 的 wp 是假。循环的近似：从假迭代 \\(\\Phi\\) 得到最弱不变式的不足逼近，有限抽象域上会停。VC 生成把用户不变式当归纳假设，检查几条蕴含。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不定义卫式命令全集，不引入概率 wp。不把抽象解释写完。后课默认：无环程序的 \\(P\\) 可算；循环要不变式或不动点。下一课格上的 Knaster–Tarski。</p><p>无环程序的 \\(P\\) 可从后往前算；循环变成谓词变换器的不动点。用户不变式是归纳假设，工具只检查蕴含。下一课用格定理保证最小/最大不动点存在。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(\\mathrm{wp}(S,Q)\\) 是使后条件成立的最弱前置。</li><li>赋值、顺序、if 有等式；while 是不动点。</li><li>Hoare 三元组 \\(=P\\Rightarrow\\mathrm{wp}\\)。</li><li>出处：Dijkstra, 1976；Winskel。</li></ul>',7))])}const P=p(d,[["render",A]]);export{D as __pageData,P as default};
